/**
 * Frontend contract types — single swap point.
 *
 * Base types are GENERATED by Backend from /shared/*.schema.json into
 * /shared/ts/index.ts (imported via the `@shared/*` tsconfig path). Do not hand-edit
 * those; regenerate with `bash shared/generate_ts.sh`.
 *
 * This file only:
 *  1. re-exports the generated types,
 *  2. narrows a few loose fields for UI use (`UiSignal` = Signal after normalizeSignal()),
 *  3. adds `@proposed` optional fields not yet in the shared schema.
 *     Each `@proposed` field must be adopted into the schema (or removed) by the team.
 */
import type * as Gen from "@shared/ts/index";

export type {
  BacktestFlag,
  BacktestIndexItem,
  BacktestIndexPage,
  Candle,
  OOSWindow,
  Trade as BacktestTrade,
  Period,
  SignalPage,
  StrategyPage,
  StreamToken,
  TenantConfig,
} from "@shared/ts/index";
export type AssetClass = Gen.AssetClass;
export type Side = Gen.Side;
export type SignalStatus = Gen.SignalStatus;
/** Schema types timeframe as string; v1 universe is fixed to these four. */
export type Timeframe = "15m" | "1h" | "4h" | "1d";

export const ASSET_CLASSES: AssetClass[] = ["crypto", "equity", "fx"];
export const TIMEFRAMES: Timeframe[] = ["15m", "1h", "4h", "1d"];
export const SIDES: Side[] = ["long", "short", "flat"];
export const SIGNAL_STATUSES: SignalStatus[] = ["active", "hit_tp", "hit_sl", "expired", "cancelled"];

/**
 * @proposed Out-of-sample validation state for a strategy / symbol-timeframe.
 * - validated: has a QA-approved walk-forward OOS backtest
 * - insufficient_oos: not enough out-of-sample history (e.g. equities & FX on 15m/1h from free feeds)
 * - pending: backtest not run or not yet QA-reviewed
 */
export type ValidationStatus = "validated" | "insufficient_oos" | "pending";

/** Wire signal (generated) + proposed fields. */
export type ApiSignal = Gen.Signal & {
  /** @proposed */
  validation_status?: ValidationStatus;
};

/** A cursor page of UI items (generated SignalPage/StrategyPage shape, items narrowed). */
export type Page<T> = { items: T[]; next_cursor?: Gen.NextCursor };

/** Signal as used by UI components: defaults filled in by normalizeSignal(). */
export type Signal = Omit<ApiSignal, "timeframe" | "take_profit" | "status" | "features_snapshot" | "entry" | "stop_loss" | "confidence_calibrated"> & {
  confidence_calibrated: boolean;
  timeframe: Timeframe;
  entry: number | null;
  stop_loss: number | null;
  take_profit: number[];
  status: SignalStatus;
  features_snapshot: Record<string, unknown>;
};

export function normalizeSignal(s: ApiSignal): Signal {
  return {
    ...s,
    timeframe: s.timeframe as Timeframe,
    entry: s.entry ?? null,
    stop_loss: s.stop_loss ?? null,
    take_profit: s.take_profit ?? [],
    status: s.status ?? "active",
    features_snapshot: s.features_snapshot ?? {},
    confidence_calibrated: s.confidence_calibrated ?? false,
  };
}

/** Backtest result (generated: full `trades` list, `trade_count`, `flags`) + proposed fields. */
/**
 * Any report the API returns is QA-approved (approval is stored server-side; the UI does not
 * read qa_approved). Headline metrics are still gated on `flags` being empty.
 */
/**
 * One report per strategy_id+version+symbol+timeframe, plus a strategy SUMMARY report where
 * symbol/timeframe are null and flags = union of all markets (all generated fields).
 */
export type BacktestReport = Gen.BacktestReport & {
  /** @proposed */
  validation_status?: ValidationStatus;
};

/** Named keys of T, without its `[k: string]: unknown` index signature (so Pick/Omit keep the real fields). */
type KnownKeys<T> = keyof { [K in keyof T as string extends K ? never : number extends K ? never : K]: T[K] };

/**
 * Generated Strategy with text fields loosened ahead of the announced schema change:
 * description / hypothesis become `string | null` and `hypothesis_id` is added. Optional until shared/ts
 * regenerates; render through lib/strategy-text.ts.
 */
export type Strategy = Pick<Gen.Strategy, Exclude<KnownKeys<Gen.Strategy>, "description" | "hypothesis">> & {
  description?: string | null;
  hypothesis?: string | null;
  /** @proposed (announced) e.g. "H1" */
  hypothesis_id?: string | null;
  timeframes: string[];
  /** @proposed */
  validation_status?: ValidationStatus;
  /** @proposed per market validation, key = `${symbol}:${timeframe}` (canonical symbol) */
  validation_by_market?: Record<string, ValidationStatus>;
};

export interface Health {
  status: string;
  [k: string]: unknown;
}
